import{_ as e,o as t,c as n,a5 as r}from"./chunks/framework.Dep_XxFZ.js";const u=JSON.parse('{"title":"更新日志 · XiHan.UI","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1787451681000}'),i={name:"changelog.md"};function a(c,o,d,l,s,g){return t(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="更新日志-·-xihan-ui" tabindex="-1">更新日志 · XiHan.UI <a class="header-anchor" href="#更新日志-·-xihan-ui" aria-label="Permalink to &quot;更新日志 · XiHan.UI&quot;">​</a></h1><p>本文件记录 XiHan.UI 各版本的变更。每条标注 <strong>新增 / 修复 / 优化 / 调整 / 移除</strong> 类别。</p><div class="warning custom-block"><p class="custom-block-title">当前是 alpha 预发布</p><p>现在的 XiHan.UI 是 2026-07-25 起从零重写的框架无关设计系统运行时，17 个公开包（<code>@xihan-ui/*</code>）由 changesets 的 <code>fixed</code> 组锁步同版，当前版本 <code>1.0.0-alpha.3</code>，<strong>已发布到 npm</strong>（<code>latest</code> 与 <code>alpha</code> 两个 dist-tag 都指向它）。它是预发布：不承诺语义化版本，接口还会变，不要用于生产。</p></div><h2 id="_1-0-0-alpha-3-2026-08-23-发布" tabindex="-1">1.0.0-alpha.3（2026-08-23 发布） <a class="header-anchor" href="#_1-0-0-alpha-3-2026-08-23-发布" aria-label="Permalink to &quot;1.0.0-alpha.3（2026-08-23 发布）&quot;">​</a></h2><p>40 份变更集，17 个公开包锁步同版。这一版的主线是<strong>一致性收口</strong>：把「同一件事在不同组件里有几种做法」逐条查出来、裁一种、再写成门禁钉住。结构门禁从 21 道增到 57 道。</p><h3 id="新增" tabindex="-1">新增 <a class="header-anchor" href="#新增" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><strong>新增</strong> <code>scrollbar</code> 组件：自绘滚动条可以挂在任意一个滚动容器上，不必是本组件的后代</li><li><strong>新增</strong> <code>date-picker</code> / <code>time-picker</code> 的快捷选项（<code>presets</code>）：给数据就在浮层里多排一列，自成一套 listbox 键盘</li><li><strong>新增</strong> 日历的多面板、按月 / 季度 / 年 / 周挑、快速翻年、周选整周预览；周序号成为一等部件 <code>week-number</code></li><li><strong>新增</strong> select 浮层的底部操作区，「新建」「全选」这类按钮有了位置</li><li><strong>新增</strong> 热力图的 <code>palette</code> 色板轴（六色），与语气轴各管各的</li><li><strong>新增</strong> number-field 的 <code>parse</code> / <code>format</code> 与可选 <code>control</code> 部件；pin-input 的 <code>pattern</code></li><li><strong>新增</strong> 全局配置做成真正的 ConfigProvider：全局默认 + 局部覆盖，两个适配器一份语义</li></ul><h3 id="调整" tabindex="-1">调整 <a class="header-anchor" href="#调整" aria-label="Permalink to &quot;调整&quot;">​</a></h3><ul><li><strong>调整</strong> <strong>浮层搬进单一落点</strong>：19 个浮层的 positioner 一律 Teleport 到 <code>#xh-portal-root</code>。宿主祖先只要建了层叠上下文，原地渲染的浮层层号就退化成局部序号——这是库无法从自身约束的。<strong>按 <code>wrapper.querySelector</code> 取浮层节点的代码要改从 <code>document</code> 取</strong></li><li><strong>调整</strong> <strong>盒的定义统一</strong>：有 <code>control</code> 部件就是盒，<code>trigger</code> 退化成盒内的 <code>flex: 1</code> 按钮。此前 16 个输入 / 选择控件有三种盒，盒是 <code>&lt;button&gt;</code> 的那五家没法把清空钮放进框里</li><li><strong>调整</strong> <strong>清空 / 关闭 / 移除按钮收成四类契约</strong>：焦点模型、空态、尺寸、圆角、互斥、文案键、键盘路径逐条统一；select / cascader / tree-select / popselect 补上了此前完全缺席的键盘清空</li><li><strong>调整</strong> <strong>状态属性收成一套词汇</strong>：当前项一律 <code>data-current</code>，<code>data-active</code> 的一名三义拆成 <code>data-in-path</code> 与 <code>data-passed</code>，组级混合态归 <code>checked | unchecked | indeterminate</code></li><li><strong>调整</strong> <strong>默认语言跟随运行时</strong>：日期系兜底从写死 <code>zh-CN</code> 改成「显式 locale → 全局配置 → 宿主语言 → <code>en-US</code>」。<strong>默认周首日随之从周一变成周日</strong>，要固定就显式传 <code>locale</code> 或 <code>firstDayOfWeek</code></li><li><strong>调整</strong> 「移除这一枚 chip / 这一行」统一叫 <code>item-delete-trigger</code>，四个文案键归成 <code>deleteItem</code></li><li><strong>调整</strong> 选择态一族（table / tree / transfer）的选中集合统一叫 <code>selection</code>，载荷键统一 <code>{ value }</code></li><li><strong>调整</strong> 兜底字形改用真图标（<code>--xh-glyph-mark-*</code> 二十个令牌），不再是跨系统长相各异的 Unicode 字符</li><li><strong>调整</strong> 减弱动效只剩一条通道，CSS 侧新增 <code>[data-motion=&#39;reduce&#39;]</code> 钩子；缓动与时长的真源是令牌</li><li><strong>调整</strong> 并排成对的面板定高——穿梭框搬走条目后整体不再变矮</li><li><strong>调整</strong> 菜单族三家（menu / menubar / context-menu）逐条同值：menubar 此前根本没有「子菜单触发项展开态」这条规则</li></ul><h3 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li><strong>修复</strong> side-nav 折叠成图标栏后，行按钮与链接<strong>没有可及名</strong>——读屏用户完全不知道每一项是什么（真机 axe 扫出，critical）</li><li><strong>修复</strong> date-picker / time-picker / combobox 有值时下拉钮被藏掉：鼠标用户没有打开入口，Escape 收起时焦点掉到 <code>body</code></li><li><strong>修复</strong> 日历周序号在周日起算时整列少 1（ISO 周里周日属于上一周）</li><li><strong>修复</strong> <code>TimeProps.locale</code> 的窄联合与全局 BCP 47 locale 对不上，配 <code>de-DE</code> 会拿到中文用词</li><li><strong>修复</strong> 4 条子路径导出的类型文件根本不存在，<code>publint</code> / <code>attw</code> 判红——发布链路当场卡住</li></ul><h3 id="优化" tabindex="-1">优化 <a class="header-anchor" href="#优化" aria-label="Permalink to &quot;优化&quot;">​</a></h3><ul><li><strong>优化</strong> 无障碍：真机 axe 覆盖到 dialog / drawer / image-viewer 三个模态，全部通过</li><li><strong>优化</strong> 新增 37 道门禁，其中 <code>check-doc-numbers</code> 把「文档里写死的数字」变成可判的——README 与文档站的组件数、令牌数、门禁道数不会再各说各话</li><li><strong>优化</strong> 版本策略页按实测重算：<code>data-state</code> 取值清单删掉 4 个库里已不存在的，WC 命令式方法从 22 条改成 29 条</li></ul><h2 id="_1-0-0-alpha-2-2026-08-16-发布" tabindex="-1">1.0.0-alpha.2（2026-08-16 发布） <a class="header-anchor" href="#_1-0-0-alpha-2-2026-08-16-发布" aria-label="Permalink to &quot;1.0.0-alpha.2（2026-08-16 发布）&quot;">​</a></h2><p>13 份变更集，17 个公开包锁步同版。<code>@xihan-ui/motion</code> 与 <code>@xihan-ui/animations</code> 是新包，这一版首次发布。</p><h3 id="新增-1" tabindex="-1">新增 <a class="header-anchor" href="#新增-1" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/motion</code> 动效原语与 <code>@xihan-ui/animations</code> 现成动效两个包，并补齐动效地基的四个缺口</li><li><strong>新增</strong> <code>@xihan-ui/icons</code> 的 SVG → <code>IconRecord</code> 构建期转换器：<code>xihan-icons</code> 命令与 <code>@xihan-ui/icons/codegen</code> 子路径，把任意 SVG 目录转成可摇树的运行期模块</li><li><strong>新增</strong> 首方图标集扩到覆盖中后台界面的常用语义，共 179 枚手绘图标，分九类；只引一枚仍是 149 B（gzip），集合变大不影响你的产物</li><li><strong>新增</strong> 自定义元素的全局文案层 <code>setXhConfig()</code></li><li><strong>新增</strong> <code>startSkinCheck()</code> 开发期探测与 <code>styles.missing-skin</code> 诊断码——漏引皮肤不再静默</li><li><strong>新增</strong> <code>check-style-entries</code> 门禁：每份皮肤都必须进得了全量入口、也够得着按需入口</li></ul><h3 id="优化-1" tabindex="-1">优化 <a class="header-anchor" href="#优化-1" aria-label="Permalink to &quot;优化&quot;">​</a></h3><ul><li><strong>优化</strong> 75 个组件的插槽写上真类型，<code>vue-tsc</code> 从此接得住插槽名与载荷键名的拼写错误</li><li><strong>优化</strong> 104 个组件全部留出 <code>&lt;Comp&gt;Translations</code> 的位，哪怕眼下一句文案都没有——后面要加时不必改结构</li><li><strong>优化</strong> 每份皮肤都能单独引入，动画不再指望别处的文件在场</li></ul><h3 id="修复-1" tabindex="-1">修复 <a class="header-anchor" href="#修复-1" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li><strong>修复</strong> 官网作为第一个真实消费方落地时暴露的四条问题（宿主定位、图层序等），全部改代码而非只改文档</li></ul><h3 id="调整-1" tabindex="-1">调整 <a class="header-anchor" href="#调整-1" aria-label="Permalink to &quot;调整&quot;">​</a></h3><ul><li><strong>调整</strong> 「collection 铺开的结构凑齐必备部件」由人工判据改成机检，三档语义写进文档</li><li><strong>调整</strong> 体积棘轮改成量使用者真正下载的那个数</li></ul><h2 id="_1-0-0-alpha-1-2026-08-13-发布" tabindex="-1">1.0.0-alpha.1（2026-08-13 发布） <a class="header-anchor" href="#_1-0-0-alpha-1-2026-08-13-发布" aria-label="Permalink to &quot;1.0.0-alpha.1（2026-08-13 发布）&quot;">​</a></h2><p>25 份变更集，15 个公开包锁步同版。<code>@xihan-ui/sound</code> 是新包，这一版首次发布；<code>@xihan-ui/icons</code> 在上一版没能发出去，这一版补齐。</p><h3 id="新增-2" tabindex="-1">新增 <a class="header-anchor" href="#新增-2" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/sound</code> 声音层：纯 Web Audio 的程序化 UI 音效，零音频文件、零第三方依赖、框架无关；命令式反馈服务已接上</li><li><strong>新增</strong> 进度条的环形与仪表盘两种形态（<code>variant</code> 由 <code>line</code> 扩成 <code>line</code> / <code>circle</code> / <code>dashboard</code>）</li><li><strong>新增</strong> 级联选择的空态兜底：<code>empty</code> 部件、<code>data-empty</code> 标记与文案覆盖</li><li><strong>新增</strong> checkbox / switch / combobox / color-picker 能进 HTML 表单，表单字段组件由 18 个变 20 个，五个缺口清完</li><li><strong>新增</strong> 复合控件响应表单重置：机制本体加 17 个组件全部接上，另立一道门禁盯着以后新加的；Web Components 侧同步</li><li><strong>新增</strong> <code>--xh-border-control</code> / <code>--xh-border-control-hover</code> 两支控件边界令牌，<code>data-contrast</code> 随之接上</li><li><strong>新增</strong> popconfirm 与 float-button 的组件文档页第一次有了 Props 表</li></ul><h3 id="修复-2" tabindex="-1">修复 <a class="header-anchor" href="#修复-2" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li><strong>修复</strong> 摇树第一次真的生效：只用一个组件不再拖来整个库。此前七个库包都是单入口打包，500+ 模块被摊平进一份 <code>dist/index.js</code>，<code>sideEffects: false</code> 随之失效。实测只用 <code>XhBadge</code> 由 168,947 B 降到 <strong>538 B</strong></li><li><strong>修复</strong> RTL 下浮层的 <code>start</code> / <code>end</code> 第一次真的翻过来</li><li><strong>修复</strong> 浮层箭头指向锚点，不再钉死在浮层中点</li><li><strong>修复</strong> <code>index.css</code> 的级联层序：层序声明挪到入口最顶，此前令牌与部分组件皮肤抢先立层</li><li><strong>修复</strong> 四处只在真实宿主里才现形的缺陷（含首屏即展开的对话框与抽屉能服务端直出、无 window 的宿主里不再抛异常）</li><li><strong>修复</strong> 带语气的 outline 控件边框补到 3:1，控件边界切到 <code>border.control</code>，WCAG SC 1.4.11 第一次真的达标</li><li><strong>修复</strong> 补齐 4 处「边框改不动」的覆盖槽</li><li><strong>修复</strong> combobox 展开按钮翻面只转箭头字形，不再带着悬停底色一起转</li><li><strong>修复</strong> 级联选择的空态占位在 Web Components 侧补齐，两个适配器不再分叉</li></ul><h3 id="调整-2" tabindex="-1">调整 <a class="header-anchor" href="#调整-2" aria-label="Permalink to &quot;调整&quot;">​</a></h3><ul><li><strong>调整</strong> 跨组件已经分叉的名字统一回一套（7 处）。part 名与 prop 名在 1.0 之后就是公开 API，趁 alpha 一次改完，逐条迁移点见各包 CHANGELOG</li><li><strong>调整</strong> 下拉与列表族的条目度量与高亮档位统一成两档制，分两批铺完 12 个组件</li><li><strong>调整</strong> 级联选择皮肤翻修：展开路径改品牌淡底加粗、分支条目补右向箭头、列改内容撑宽定高</li><li><strong>调整</strong> <code>hideOutside</code> 的入参形状随真实宿主那四处修复一并变化</li></ul><h2 id="_1-0-0-alpha-0-·-框架无关重写-2026-07-25-起-2026-08-11-发布" tabindex="-1">1.0.0-alpha.0 · 框架无关重写（2026-07-25 起，2026-08-11 发布） <a class="header-anchor" href="#_1-0-0-alpha-0-·-框架无关重写-2026-07-25-起-2026-08-11-发布" aria-label="Permalink to &quot;1.0.0-alpha.0 · 框架无关重写（2026-07-25 起，2026-08-11 发布）&quot;">​</a></h2><h3 id="基座" tabindex="-1">基座 <a class="header-anchor" href="#基座" aria-label="Permalink to &quot;基座&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/kernel</code> 结构原语：anatomy、<code>mergeProps</code>、<code>normalizeProps</code>、Scope、context、id 生成，以及浮层定位、虚拟滚动、代码着色三个端口的类型契约</li><li><strong>新增</strong> <code>@xihan-ui/machine</code> 自研薄状态机：定义层、<code>createService</code> 解释器与 vanilla 运行时，受控值绑定与效应生命周期</li><li><strong>新增</strong> <code>@xihan-ui/behavior</code> 交互行为原语：消解层、焦点域、滚动锁、进出场，随后补上条目集合导航（roving tabindex 底座）与首字母连打检索</li><li><strong>新增</strong> <code>@xihan-ui/tokens</code> 设计令牌体系与主题运行时，令牌从 DTCG 源产出 CSS / JSON / TS 三种形态</li><li><strong>新增</strong> <code>@xihan-ui/styles</code> 纯 CSS 皮肤层，后续补上 reset 层</li><li><strong>新增</strong> <code>@xihan-ui/kernel</code> 全局诊断通道，状态机错误投递进该通道而不是抛在使用者脸上</li></ul><h3 id="适配器" tabindex="-1">适配器 <a class="header-anchor" href="#适配器" aria-label="Permalink to &quot;适配器&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/vue</code> Vue 3 适配器，Button / Dialog 纵切片先打穿全链路</li><li><strong>新增</strong> <code>@xihan-ui/web-components</code> Web Components 适配器，Light DOM 行为宿主；<code>xh-dialog</code> 把「有状态组件也能框架无关」这件事验证掉</li><li><strong>新增</strong> WC 侧观察 Light DOM 增删并重新接线，抹平「运行期增删条目」上的适配器分叉</li><li><strong>新增</strong> WC 角色节点契约校验与 Custom Elements Manifest 生成，两者都进门禁</li><li><strong>新增</strong> 跨适配器一致性套件（conformance）：同一批判据在两套宿主上逐帧比对归一化后的 DOM，套件数从 1 个扩到 102 个，排除项改为显式登记</li><li><strong>调整</strong> playground 拆成 <code>playground-vue</code> 与 <code>playground-wc</code> 两个独立包，一环境一包</li></ul><h3 id="组件" tabindex="-1">组件 <a class="header-anchor" href="#组件" aria-label="Permalink to &quot;组件&quot;">​</a></h3><ul><li><strong>新增</strong> 102 个组件逐批铺开，每个都同时产出无头内核、Vue 组件、自定义元素与默认皮肤：从 Button / Dialog 起，经 Switch、Checkbox / Collapsible / Separator、Toggle / Progress / Badge、RadioGroup / Tabs / Accordion、Tooltip / Popover、Menu、Select / Avatar / Field、NumberField，到日期族与最后一批，双适配器铺满</li><li><strong>新增</strong> alert / spinner / skeleton / empty-state 四个反馈类组件</li><li><strong>新增</strong> Checkbox 三态</li><li><strong>调整</strong> Select 支持多选，选中值由单值改为集合：<code>SelectValueChangeDetails.value</code> 由 <code>string | null</code> 变 <code>string[]</code>，<code>SelectApi</code> 的 <code>value</code> / <code>valueText</code> 变数组，<code>setValue</code> 签名变 <code>(next: string | string[]) =&gt; void</code>；Vue 侧 <code>update:value</code> 载荷与 WC 侧 <code>value-change</code> 的 <code>detail</code> 随之变化。见<a href="./components/select">选择器</a></li></ul><h3 id="视觉词汇表" tabindex="-1">视觉词汇表 <a class="header-anchor" href="#视觉词汇表" aria-label="Permalink to &quot;视觉词汇表&quot;">​</a></h3><ul><li><strong>新增</strong> 三个正交的视觉轴：<code>variant</code> 形态（<code>solid</code> / <code>subtle</code> / <code>outline</code> / <code>ghost</code>）、<code>tone</code> 语气（<code>brand</code> / <code>neutral</code> / <code>success</code> / <code>warning</code> / <code>danger</code> / <code>info</code>）、<code>size</code> 尺寸（<code>sm</code> / 缺省 / <code>lg</code>）。语气做成与组件无关的共享一层，各组件的形态规则只消费它声明的私有槽——加一个语气改一处，不是逐个组件写六遍</li><li><strong>新增</strong> 34 个组件接入这套词汇表：按钮族与表单控件、十个输入类组件、以及标签页、步骤条、菜单族、分页、表格、对话框、抽屉等。没写轴的组件外观与接入前逐值一致</li><li><strong>调整</strong> 实心底上的前景色按实测对比度分派而非统一白字：600 档上白字对 brand 5.08、neutral 7.80、danger 4.83 达标，而 success 3.04、warning 2.70、info 3.47 都不到 4.5，这三族配深字</li><li><strong>调整</strong> 破坏性变更：<code>alert</code> 的 <code>variant</code> 改名为 <code>tone</code>。它原本的取值是 <code>success</code> / <code>warning</code> / <code>danger</code>——那是语气不是形态，与全库词汇表冲突。取值不变，只改属性名；同时移除公开导出的 <code>AlertVariant</code> 类型</li><li><strong>调整</strong> <code>toast</code> 的配色改走共享语气层，由 <code>type</code> 内部派生（<code>error</code> → <code>danger</code>，<code>loading</code> → 中性），公开 API 不变</li><li><strong>调整</strong> 三条轴由裸 <code>string</code> 收成联合类型，从 <code>@xihan-ui/kernel</code> 导出：<code>Tone</code>（六档）、<code>Size</code>（<code>sm</code> / <code>md</code> / <code>lg</code>）、<code>ControlVariant</code>（<code>outline</code> / <code>subtle</code> / <code>ghost</code>，十二个输入控件）与 <code>ActionVariant</code>（前者再加 <code>solid</code>，按钮族）</li><li><strong>修复</strong> <code>checkbox</code> 半选态的横杠此前不可见：方框只在全选时填色，半选保持画布底，而横杠用的是实心底上的前景色，白压白等于没画</li></ul><h3 id="自研替换第三方" tabindex="-1">自研替换第三方 <a class="header-anchor" href="#自研替换第三方" aria-label="Permalink to &quot;自研替换第三方&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/position</code> 自研浮层定位引擎（包含块解析、缩放换算、翻面与避让、跟随更新），<strong>移除</strong> <code>@floating-ui/dom</code></li><li><strong>新增</strong> 自研虚拟滚动内核，<strong>移除</strong> <code>@tanstack/virtual-core</code></li><li><strong>新增</strong> WC 自研响应式基类，<strong>移除</strong> <code>@lit/reactive-element</code></li><li><strong>新增</strong> <code>@xihan-ui/markdown</code> 自研解析与渲染，<strong>移除</strong> <code>markdown-it</code></li><li><strong>新增</strong> 代码着色走端口，内置自研粗粒度词法器，可换 Shiki</li><li><strong>调整</strong> 至此全部库包的运行时第三方依赖只剩一个（<code>@internationalized/date</code>，仅日期族使用）。见<a href="./npm-package-dependency">包与依赖关系</a></li></ul><h3 id="ai-与-markdown" tabindex="-1">AI 与 Markdown <a class="header-anchor" href="#ai-与-markdown" aria-label="Permalink to &quot;AI 与 Markdown&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/chat-stream</code> 协议内核与 AI 组件族第一批：SSE 读取、协议归一、parts 归约、会话 store，配 Thread / Composer / CodeBlock 三件与粘底原语，双适配器</li><li><strong>新增</strong> <code>@xihan-ui/markdown</code> 流式渲染内核，增量切块 + 稳定 key + 消毒</li><li><strong>优化</strong> Markdown 接上 CommonMark 官方用例的一致率棘轮，逐步实现缩进代码块、Setext 标题、跨行链接引用定义与列表松紧排布，一致率由 375 提升至 489</li></ul><h3 id="视觉层" tabindex="-1">视觉层 <a class="header-anchor" href="#视觉层" aria-label="Permalink to &quot;视觉层&quot;">​</a></h3><ul><li><strong>新增</strong> <code>@xihan-ui/backgrounds</code>：WebGL2 背景效果与数据驱动粒子点云，框架无关、零第三方依赖。流场跑片元着色器、粒子走 <code>gl.POINTS</code>，两通道共用同一段 GLSL；内置 14 个效果，不支持 WebGL2 时降级为 CSS 静态背景</li><li><strong>新增</strong> 两个适配器接上视觉层，各走独立子入口 <code>@xihan-ui/vue/backgrounds</code> 与 <code>@xihan-ui/web-components/backgrounds</code>，<code>@xihan-ui/backgrounds</code> 声明为可选 peer</li><li><strong>修复</strong> 修复画面在真实页面里一片空白的三个成因</li></ul><h3 id="图标" tabindex="-1">图标 <a class="header-anchor" href="#图标" aria-label="Permalink to &quot;图标&quot;">​</a></h3><ul><li><strong>新增</strong> Icon 原语：<code>IconRecord</code> / <code>IconNode</code> / <code>IconTag</code> 类型、<code>connectIcon</code>、<code>XhIcon</code>、<code>&lt;xh-icon&gt;</code> 与 <code>icon.css</code>。图标数据是结构化节点数组而非 SVG 字符串，渲染端逐节点建元素，运行期不经 HTML 解析器</li><li><strong>移除</strong> 旧 <code>@xihan-ui/icons</code>（27 个第三方图标集的聚合，约四万个图标）整包移除并在 npm 上弃用，重写为只收自研图标的首方集，第一批 29 个覆盖组件库自用的全部语义</li></ul><h3 id="无障碍与质量门禁" tabindex="-1">无障碍与质量门禁 <a class="header-anchor" href="#无障碍与质量门禁" aria-label="Permalink to &quot;无障碍与质量门禁&quot;">​</a></h3><ul><li><strong>新增</strong> 无障碍扫描接上真实浏览器 runner 与 axe，逐个组件扫</li><li><strong>新增</strong> 键盘规格表机读化，作为测试的分母：用例少覆盖一条即判套件失败</li><li><strong>新增</strong> 产物契约门禁（publint + attw）、foundation 层框架无关门禁、依赖拓扑门禁</li><li><strong>修复</strong> 存量无障碍违规登记表清零，由 24 条降到 2 条（WC 侧 <code>steps</code> 一条，外加一条步骤重放豁免）</li><li><strong>修复</strong> 令牌 <code>fg-subtle</code> 达到 AA，并给对比度立下判据</li><li><strong>修复</strong> 焦点陷阱抓不住第一次逃逸；移除持有焦点的条目后不再让整组脱离 Tab 序列；删掉文件上传条目后把焦点交回投放区</li><li><strong>修复</strong> 浮层族改用 fixed 坐标系，不再被 overflow 祖先裁掉</li><li><strong>修复</strong> 挡住输入法组合态</li><li><strong>修复</strong> Dialog 三处：模态背景失活、非模态焦点域、收起态 hidden</li><li><strong>修复</strong> Field 的名字关联不再依赖 control 是可标注元素；Splitter root 不再输出 <code>aria-orientation</code></li><li><strong>修复</strong> 消解层只在展开期间入栈，不再与开合无关地常驻</li><li><strong>修复</strong> 状态机停机后送入的事件一律静默丢弃，dev 下不再抛</li></ul><h3 id="工程" tabindex="-1">工程 <a class="header-anchor" href="#工程" aria-label="Permalink to &quot;工程&quot;">​</a></h3><ul><li><strong>调整</strong> 皮肤层令牌成为唯一事实源，删掉全部字面量兜底，跨组件共享的默认值全部令牌化</li><li><strong>调整</strong> 全仓注释改为只讲功能，不带设计过程引用</li><li><strong>调整</strong> 行尾一律 LF（<code>.gitattributes</code>），署名统一为 XiHanFun and contributors</li><li><strong>新增</strong> changesets 发布配置就绪：14 个公开包锁步同版，私有包不发布不计版</li></ul>',52)])])}const p=e(i,[["render",a]]);export{u as __pageData,p as default};
